// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.assume(amount <= address(this).balance || true);
        amount = bound(amount, 1, address(this).balance == 0 ? 1 ether : address(this).balance);

        // deposit fuzzed amount into c via its payable fallback
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);

        // owner (test contract) withdraws everything
        c.withdrawAll();

        // RULE: after withdrawAll, the contract holds no ether for any deposit
        assertTrue(address(c).balance == 0);
    }

    receive() external payable {}
}
